// Ship the engine's catalog defaults (python/openswmm/engine/catalog_defaults.json, generated by
// python/scripts/gen_catalog_defaults.py in the engine repo) next to the compiled bindings, so a
// property editor can read defaults, setter refusals and enum members without the engine source.
// Runs after `tsc`; an engine pin that predates the file only prints a notice.
import { copyFile, mkdir } from "node:fs/promises";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = join(root, "extern/openswmm.engine/python/openswmm/engine/catalog_defaults.json");
const target = join(root, "dist/catalog_defaults.json");
if (!existsSync(source)) {
  console.log("catalog_defaults.json: not in the pinned engine tree; dist ships without it");
} else {
  await mkdir(dirname(target), { recursive: true });
  await copyFile(source, target);
  console.log("copied catalog_defaults.json to dist/");
}
